return [
    'maps docx core properties styles hyperlinks numbering and media from package parts' => static function (TestRunner $t): void {
        $document = (new DocxOpenXmlReader())->readPackage(docx_openxml_reader_fixture_parts());

        $meta = $document->attr('meta');
        $docx = $document->attr('docx');
        $heading = $document->children[0];
        $paragraph = $document->children[1];
        $ordered = $document->children[2];
        $bullet = $document->children[3];
        $imageParagraph = $document->children[4];
        $table = $document->children[5];

        $t->same('Imported DOCX Batch', $meta['title']);
        $t->same(['Migration Editor'], $meta['authors']);
        $t->same('word/document.xml', $docx['documentPart']);
        $t->same('application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml', $docx['contentTypes']['overrides']['word/document.xml']);
        $t->same('docProps/core.xml', $docx['corePropertiesPart']);
        $t->same('word/styles.xml', $docx['stylesPart']);
        $t->same('rCore', $docx['corePropertiesRelationship']['id']);
        $t->same('docProps/core.xml', $docx['corePropertiesRelationship']['targetPart']);
        $t->true(!isset($docx['stylesRelationship']), 'conventional DOCX styles fallback should not invent relationship metadata');
        $t->same('word/numbering.xml', $docx['numberingPart']);
        $t->true(!isset($docx['numberingRelationship']), 'conventional DOCX numbering fallback should not invent relationship metadata');
        $t->same('image/png', $docx['media']['word/media/review.png']['contentType']);
        $t->same(strlen('fake png bytes'), $docx['media']['word/media/review.png']['size']);

        $t->same('heading', $heading->type);
        $t->same(1, $heading->attr('level'));
        $t->same('imported-docx-heading', $heading->attr('id'));
        $t->same('Heading 1', $heading->attr('docxStyleName'));
        $t->same('strong', $paragraph->children[1]->type);
        $t->same('emph', $paragraph->children[3]->type);
        $t->same('underline', $paragraph->children[5]->type);
        $t->same('strikeout', $paragraph->children[7]->type);
        $t->same('superscript', $paragraph->children[9]->type);
        $t->same('link', $paragraph->children[11]->type);
        $t->same('https://example.test/source?post=42', $paragraph->children[11]->attr('url'));
        $t->same('rLink', $paragraph->children[11]->attr('relationshipId'));

        $t->same('ordered_list', $ordered->type);
        $t->same(3, $ordered->attr('start'));
        $t->same('upper_roman', $ordered->attr('style'));
        $t->same('one_paren', $ordered->attr('delimiter'));
        $t->same('First review step', $ordered->children[0]->children[0]->attr('text'));
        $t->same('Second review step', $ordered->children[1]->children[0]->attr('text'));
        $t->same('bullet_list', $bullet->type);
        $t->same('•', $bullet->attr('bulletChar'));
        $t->same('Bullet media note', $bullet->children[0]->children[0]->attr('text'));

        $image = $imageParagraph->children[1];
        $t->same('image', $image->type);
        $t->same('word/media/review.png', $image->attr('url'));
        $t->same('Review screenshot', $image->attr('alt'));
        $t->same('Review image', $image->attr('title'));
        $t->same('image/png', $image->attr('contentType'));
        $t->same('table', $table->type);
        $t->same('Reviewer', $table->children[0]->children[0]->children[0]->attr('text'));
        $t->same(2, $table->children[0]->children[0]->children[1]->attr('colspan'));
    },
    'preserves docx table omitted grid columns header rows and vertical merge metadata' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['word/document.xml'] = str_replace(
            <<<'XML'
    <w:tbl>
      <w:tr><w:tc><w:p><w:r><w:t>Reviewer</w:t></w:r></w:p></w:tc><w:tc><w:tcPr><w:gridSpan w:val="2"/></w:tcPr><w:p><w:r><w:t>Approved</w:t></w:r></w:p></w:tc></w:tr>
    </w:tbl>
XML,
            <<<'XML'
    <w:tbl>
      <w:tr>
        <w:trPr><w:tblHeader w:val="1"/><w:gridBefore w:val="1"/><w:gridAfter w:val="1"/></w:trPr>
        <w:tc><w:p><w:r><w:t>Region</w:t></w:r></w:p></w:tc>
        <w:tc><w:tcPr><w:gridSpan w:val="2"/></w:tcPr><w:p><w:r><w:t>Reviewer result</w:t></w:r></w:p></w:tc>
      </w:tr>
      <w:tr>
        <w:trPr><w:gridBefore w:val="1"/></w:trPr>
        <w:tc><w:tcPr><w:vMerge w:val="restart"/></w:tcPr><w:p><w:r><w:t>North</w:t></w:r></w:p></w:tc>
        <w:tc><w:p><w:r><w:t>Approved</w:t></w:r></w:p></w:tc>
      </w:tr>
      <w:tr>
        <w:trPr><w:gridBefore w:val="1"/><w:gridAfter w:val="2"/></w:trPr>
        <w:tc><w:tcPr><w:vMerge/></w:tcPr><w:p/></w:tc>
        <w:tc><w:p><w:r><w:t>Pending</w:t></w:r></w:p></w:tc>
      </w:tr>
    </w:tbl>
XML,
            $parts['word/document.xml']
        );

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $table = $document->children[5];
        $head = $table->children[0];
        $body = $table->children[1];
        $headerRow = $head->children[0];
        $restartRow = $body->children[0];
        $continueRow = $body->children[1];
        $blocks = (new WordPressBlockWriter())->write($document);

        $t->same('table_head', $head->type);
        $t->same('table_body', $body->type);
        $t->same('docx-table-grid-merge-metadata-only', $table->attr('docxTableMetadataPolicy'));
        $t->same(3, $table->attr('docxTableRowCount'));
        $t->same(1, $table->attr('docxTableHeadRowCount'));
        $t->same(2, $table->attr('docxTableBodyRowCount'));
        $t->same(3, $table->attr('docxTableGridBeforeRowCount'));
        $t->same(2, $table->attr('docxTableGridAfterRowCount'));
        $t->same(3, $table->attr('docxTableOmittedBeforeColumnCount'));
        $t->same(3, $table->attr('docxTableOmittedAfterColumnCount'));
        $t->same(1, $table->attr('docxTableHeaderRowCount'));
        $t->same(2, $table->attr('docxTableVerticalMergeCellCount'));
        $t->same(1, $table->attr('docxTableVerticalMergeRestartCount'));
        $t->same(1, $table->attr('docxTableVerticalMergeContinueCount'));
        $t->same(5, $table->attr('docxTableMaxGridColumnCount'));

        $t->same(true, $headerRow->attr('header'));
        $t->same(true, $headerRow->attr('docxTableHeader'));
        $t->same(1, $headerRow->attr('docxGridBefore'));
        $t->same(1, $headerRow->attr('docxGridAfter'));
        $t->same(5, $headerRow->attr('docxGridColumnCount'));
        $t->same(true, $headerRow->children[0]->attr('header'));
        $t->same(2, $headerRow->children[0]->attr('docxGridColumn'));
        $t->same(1, $headerRow->children[0]->attr('docxGridSpan'));
        $t->same(true, $headerRow->children[1]->attr('header'));
        $t->same(3, $headerRow->children[1]->attr('docxGridColumn'));
        $t->same(2, $headerRow->children[1]->attr('docxGridSpan'));
        $t->same(2, $headerRow->children[1]->attr('colspan'));

        $t->same('restart', $restartRow->children[0]->attr('docxVerticalMerge'));
        $t->same(2, $restartRow->children[0]->attr('docxGridColumn'));
        $t->same('North', $restartRow->children[0]->attr('text'));
        $t->same('continue', $continueRow->children[0]->attr('docxVerticalMerge'));
        $t->same('', $continueRow->children[0]->attr('text'));
        $t->same(2, $continueRow->attr('docxGridAfter'));
        $t->same(5, $continueRow->attr('docxGridColumnCount'));

        $t->contains('<thead><tr><th><p>Region</p></th><th colspan="2"><p>Reviewer result</p></th></tr></thead>', $blocks);
        $t->true(!str_contains($blocks, 'docxTableMetadataPolicy'), 'DOCX table metadata should not leak into rendered blocks');
    },
    'summarizes docx body revision text provenance without accepting deleted text' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['word/document.xml'] = str_replace(
            '  </w:body>',
            <<<'XML'
    <w:p>
      <w:r><w:t xml:space="preserve">Visible </w:t></w:r>
      <w:ins w:id="1" w:author="Reviewer" w:date="2026-07-01T10:00:00Z"><w:r><w:t>accepted</w:t></w:r></w:ins>
      <w:del w:id="2" w:author="Reviewer" w:date="2026-07-01T10:05:00Z"><w:r><w:delText>discarded</w:delText></w:r></w:del>
      <w:moveFrom w:id="3" w:author="Editor" w:date="2026-07-01T10:10:00Z"><w:r><w:t>old location</w:t></w:r></w:moveFrom>
      <w:r><w:t xml:space="preserve"> </w:t></w:r>
      <w:moveTo w:id="4" w:author="Editor" w:date="2026-07-01T10:15:00Z"><w:r><w:t>new location</w:t></w:r></w:moveTo>
    </w:p>
  </w:body>
XML,
            $parts['word/document.xml']
        );

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $docx = $document->attr('docx');
        $revisions = $docx['documentRevisions'];
        $summary = $docx['packageProvenance']['summary'];
        $revisionParagraph = $document->children[6];
        $totalRevisionBytes = strlen('accepted') + strlen('discarded') + strlen('old location') + strlen('new location');

        $t->same('paragraph', $revisionParagraph->type);
        $t->same('Visible accepted new location', $revisionParagraph->attr('text'));
        $t->true(!str_contains($revisionParagraph->attr('text'), 'discarded'), 'deleted body text must not be accepted into the paragraph');
        $t->true(!str_contains($revisionParagraph->attr('text'), 'old location'), 'moved-from body text must not be accepted into the paragraph');

        $t->same('word/document.xml', $revisions['partName']);
        $t->same(4, $revisions['count']);
        $t->same(2, $revisions['visibleCount']);
        $t->same(2, $revisions['reviewOnlyCount']);
        $t->same(['ins' => 1, 'del' => 1, 'moveFrom' => 1, 'moveTo' => 1], $revisions['kindCounts']);
        $t->same(['Reviewer', 'Editor'], $revisions['authors']);
        $t->same(2, $revisions['authorCount']);
        $t->same(4, $revisions['datedCount']);
        $t->same(4, $revisions['textRunCount']);
        $t->same($totalRevisionBytes, $revisions['textBytes']);
        $t->same(0, $revisions['emptyTextCount']);
        $t->same('body-revision-text-metadata-only', $revisions['reviewPolicy']);

        $t->same('ins', $revisions['items'][0]['kind']);
        $t->same(true, $revisions['items'][0]['visibleInBodyText']);
        $t->same('body-revision-visible', $revisions['items'][0]['reviewPolicy']);
        $t->same(hash('sha256', 'accepted'), $revisions['items'][0]['textSha256']);
        $t->same(['t'], $revisions['items'][0]['textElementNames']);

        $t->same('del', $revisions['items'][1]['kind']);
        $t->same(false, $revisions['items'][1]['visibleInBodyText']);
        $t->same('body-revision-text-metadata-only', $revisions['items'][1]['reviewPolicy']);
        $t->same(strlen('discarded'), $revisions['items'][1]['textBytes']);
        $t->same(hash('sha256', 'discarded'), $revisions['items'][1]['textSha256']);
        $t->true(!isset($revisions['items'][1]['text']), 'deleted text must stay metadata-only');
        $t->same(['delText'], $revisions['items'][1]['textElementNames']);

        $t->same('moveFrom', $revisions['items'][2]['kind']);
        $t->same(false, $revisions['items'][2]['visibleInBodyText']);
        $t->same(hash('sha256', 'old location'), $revisions['items'][2]['textSha256']);
        $t->true(!isset($revisions['items'][2]['text']), 'moved-from text must stay metadata-only');

        $t->same('moveTo', $revisions['items'][3]['kind']);
        $t->same(true, $revisions['items'][3]['visibleInBodyText']);
        $t->same(hash('sha256', 'new location'), $revisions['items'][3]['textSha256']);

        $t->same(4, $summary['documentRevisionCount']);
        $t->same(2, $summary['documentRevisionVisibleCount']);
        $t->same(2, $summary['documentRevisionReviewOnlyCount']);
        $t->same(['ins' => 1, 'del' => 1, 'moveFrom' => 1, 'moveTo' => 1], $summary['documentRevisionKindCounts']);
        $t->same(['Reviewer', 'Editor'], $summary['documentRevisionAuthors']);
        $t->same($totalRevisionBytes, $summary['documentRevisionTextBytes']);
        $t->same('body-revision-text-metadata-only', $summary['documentRevisionReviewPolicy']);
    },
    'summarizes docx body range marker provenance without exposing marker names' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['word/document.xml'] = str_replace(
            '  </w:body>',
            <<<'XML'
    <w:p>
      <w:bookmarkStart w:id="7" w:name="Review Anchor"/>
      <w:r><w:t>Bookmarked</w:t></w:r>
      <w:bookmarkEnd w:id="7"/>
      <w:r><w:t xml:space="preserve"> </w:t></w:r>
      <w:commentRangeStart w:id="12"/>
      <w:r><w:t>commented</w:t></w:r>
      <w:commentRangeEnd w:id="12"/>
      <w:r><w:t xml:space="preserve"> </w:t></w:r>
      <w:proofErr w:type="spellStart"/>
      <w:r><w:t>typo</w:t></w:r>
      <w:proofErr w:type="spellEnd"/>
      <w:r><w:t xml:space="preserve"> </w:t></w:r>
      <w:permStart w:id="9" w:edGrp="everyone" w:colFirst="1" w:colLast="2"/>
      <w:r><w:t>protected</w:t></w:r>
      <w:permEnd w:id="9"/>
      <w:moveFromRangeStart w:id="21"/>
      <w:moveFromRangeEnd w:id="21"/>
      <w:moveToRangeStart w:id="22"/>
      <w:moveToRangeEnd w:id="22"/>
    </w:p>
  </w:body>
XML,
            $parts['word/document.xml']
        );

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $docx = $document->attr('docx');
        $markers = $docx['documentRangeMarkers'];
        $summary = $docx['packageProvenance']['summary'];
        $markerParagraph = $document->children[6];
        $expectedKindCounts = [
            'bookmark' => 2,
            'comment' => 2,
            'proofError' => 2,
            'permission' => 2,
            'moveFrom' => 2,
            'moveTo' => 2,
            'customXmlInsert' => 0,
            'customXmlDelete' => 0,
            'customXmlMoveFrom' => 0,
            'customXmlMoveTo' => 0,
        ];
        $expectedElementCounts = [
            'bookmarkStart' => 1,
            'bookmarkEnd' => 1,
            'commentRangeStart' => 1,
            'commentRangeEnd' => 1,
            'proofErr' => 2,
            'permStart' => 1,
            'permEnd' => 1,
            'moveFromRangeStart' => 1,
            'moveFromRangeEnd' => 1,
            'moveToRangeStart' => 1,
            'moveToRangeEnd' => 1,
        ];

        $t->same('paragraph', $markerParagraph->type);
        $t->same('Bookmarked commented typo protected', $markerParagraph->attr('text'));
        $t->same('word/document.xml', $markers['partName']);
        $t->same(12, $markers['count']);
        $t->same($expectedKindCounts, $markers['kindCounts']);
        $t->same($expectedElementCounts, $markers['elementCounts']);
        $t->same(['start' => 5, 'end' => 5, 'point' => 2], $markers['positionCounts']);
        $t->same(5, $markers['startCount']);
        $t->same(5, $markers['endCount']);
        $t->same(2, $markers['pointCount']);
        $t->same(0, $markers['emptyIdCount']);
        $t->same(1, $markers['namedBookmarkCount']);
        $t->same(1, $markers['nameHashCount']);
        $t->same(2, $markers['typedProofErrorCount']);
        $t->same(1, $markers['permissionEditorGroupCount']);
        $t->same(1, $markers['permissionColumnBoundCount']);
        $t->same('body-range-marker-metadata-only', $markers['reviewPolicy']);

        $t->same('bookmarkStart', $markers['items'][0]['element']);
        $t->same('bookmark', $markers['items'][0]['kind']);
        $t->same('start', $markers['items'][0]['position']);
        $t->same('7', $markers['items'][0]['id']);
        $t->same(strlen('Review Anchor'), $markers['items'][0]['nameBytes']);
        $t->same(hash('sha256', 'Review Anchor'), $markers['items'][0]['nameSha256']);
        $t->true(!isset($markers['items'][0]['name']), 'bookmark names must stay hashed metadata');
        $t->true(!str_contains(json_encode($markers, JSON_THROW_ON_ERROR), 'Review Anchor'), 'raw marker names must not appear in provenance');

        $t->same('proofErr', $markers['items'][4]['element']);
        $t->same('spellStart', $markers['items'][4]['proofErrorType']);
        $t->same('spellEnd', $markers['items'][5]['proofErrorType']);
        $t->same('permStart', $markers['items'][6]['element']);
        $t->same('everyone', $markers['items'][6]['editorGroup']);
        $t->same(1, $markers['items'][6]['columnFirst']);
        $t->same(2, $markers['items'][6]['columnLast']);
        $t->same('moveFromRangeStart', $markers['items'][8]['element']);
        $t->same('moveToRangeEnd', $markers['items'][11]['element']);

        $t->same(12, $summary['documentRangeMarkerCount']);
        $t->same($expectedKindCounts, $summary['documentRangeMarkerKindCounts']);
        $t->same($expectedElementCounts, $summary['documentRangeMarkerElementCounts']);
        $t->same(1, $summary['documentRangeMarkerNamedBookmarkCount']);
        $t->same(2, $summary['documentRangeMarkerTypedProofErrorCount']);
        $t->same('body-range-marker-metadata-only', $summary['documentRangeMarkerReviewPolicy']);
    },
    'normalizes docx drawing image target suffixes while preserving package provenance' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['word/_rels/document.xml.rels'] = str_replace(
            'Target="media/review.png"',
            'Target="media/review.png?display=preview#inline"',
            $parts['word/_rels/document.xml.rels']
        );

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $docx = $document->attr('docx');
        $image = $document->children[4]->children[1];
        $relationship = $docx['packageProvenance']['relationshipParts']['word/_rels/document.xml.rels']['relationships']['rImage'];
        $markdown = (new MarkdownWriter())->write($document);
        $blocks = (new WordPressBlockWriter())->write($document);

        $t->same('word/media/review.png', $image->attr('url'));
        $t->same('word/media/review.png', $image->attr('mediaPath'));
        $t->same('media/review.png?display=preview#inline', $image->attr('target'));
        $t->same('word/media/review.png?display=preview#inline', $image->attr('resolvedTarget'));
        $t->same('word/media/review.png', $image->attr('targetPart'));
        $t->same('display=preview', $image->attr('targetQuery'));
        $t->same('inline', $image->attr('targetFragment'));
        $t->same('?display=preview#inline', $image->attr('targetReferenceSuffix'));
        $t->same('image/png', $image->attr('contentType'));
        $t->same(strlen('fake png bytes'), $docx['media']['word/media/review.png']['size']);

        $t->same('media/review.png?display=preview#inline', $relationship['target']);
        $t->same('word/media/review.png?display=preview#inline', $relationship['resolvedTarget']);
        $t->same('word/media/review.png', $relationship['targetPart']);
        $t->same('display=preview', $relationship['targetQuery']);
        $t->same('inline', $relationship['targetFragment']);
        $t->same('?display=preview#inline', $relationship['targetReferenceSuffix']);
        $t->contains('![Review screenshot](word/media/review.png "Review image")', $markdown);
        $t->contains('<img src="word/media/review.png" alt="Review screenshot" title="Review image"/>', $blocks);
    },
    'exposes docx package content type relationship and part inventory provenance' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['[Content_Types].xml'] = str_replace(
            '</Types>',
            '  <Override PartName="/customXml/item1.xml" ContentType="application/xml"/>' . "\n" .
            '  <Override PartName="/word/missing-comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/>' . "\n" .
            '</Types>',
            $parts['[Content_Types].xml']
        );
        $parts['_rels/.rels'] = str_replace(
            'Target="word/document.xml"',
            'Target="word/document.xml?doc=main#body"',
            $parts['_rels/.rels']
        );
        $parts['word/_rels/document.xml.rels'] = str_replace(
            '</Relationships>',
            '  <Relationship Id="rCustomXml" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/customXml" Target="../customXml/item1.xml?slot=1#payload"/>' . "\n" .
            '  <Relationship Id="rRemote" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="https://example.test/reference.xml?x=1#frag" TargetMode="External"/>' . "\n" .
            '</Relationships>',
            $parts['word/_rels/document.xml.rels']
        );
        $parts['customXml/item1.xml'] = '<root/>';

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $package = $document->attr('docx')['packageProvenance'];
        $contentTypesPart = $package['contentTypesPart'];
        $rootRelationshipsPart = $package['relationshipParts']['_rels/.rels'];
        $documentRelationshipsPart = $package['relationshipParts']['word/_rels/document.xml.rels'];
        $customXmlRelationship = $documentRelationshipsPart['relationships']['rCustomXml'];
        $remoteRelationship = $documentRelationshipsPart['relationships']['rRemote'];
        $inventory = $package['parts'];

        $t->same('[Content_Types].xml', $contentTypesPart['partName']);
        $t->same(true, $contentTypesPart['exists']);
        $t->same(strlen($parts['[Content_Types].xml']), $contentTypesPart['bytes']);
        $t->same('application/xml', $contentTypesPart['defaults']['xml']['contentType']);
        $t->same('application/xml', $contentTypesPart['overrides']['customXml/item1.xml']['contentType']);
        $t->same(true, $contentTypesPart['overrides']['customXml/item1.xml']['exists']);
        $t->same(false, $contentTypesPart['overrides']['word/missing-comments.xml']['exists']);

        $t->same('word/document.xml', $package['documentPart']);
        $t->same('/', $rootRelationshipsPart['sourcePart']);
        $t->same(true, $rootRelationshipsPart['exists']);
        $t->same('word/document.xml?doc=main#body', $rootRelationshipsPart['relationships']['rDoc']['resolvedTarget']);
        $t->same('word/document.xml', $rootRelationshipsPart['relationships']['rDoc']['targetPart']);
        $t->same('?doc=main#body', $rootRelationshipsPart['relationships']['rDoc']['targetReferenceSuffix']);
        $t->same(true, $rootRelationshipsPart['relationships']['rDoc']['exists']);
        $t->same('override', $rootRelationshipsPart['relationships']['rDoc']['contentTypeSource']);
        $t->same('word/document.xml', $documentRelationshipsPart['sourcePart']);
        $t->same(true, $documentRelationshipsPart['exists']);
        $t->same(4, $documentRelationshipsPart['relationshipCount']);
        $t->same('customXml/item1.xml?slot=1#payload', $customXmlRelationship['resolvedTarget']);
        $t->same('customXml/item1.xml', $customXmlRelationship['targetPart']);
        $t->same('?slot=1#payload', $customXmlRelationship['targetReferenceSuffix']);
        $t->same('slot=1', $customXmlRelationship['targetQuery']);
        $t->same('payload', $customXmlRelationship['targetFragment']);
        $t->same(true, $customXmlRelationship['exists']);
        $t->same('override', $customXmlRelationship['contentTypeSource']);
        $t->same(true, $remoteRelationship['external']);
        $t->same(null, $remoteRelationship['targetPart']);
        $t->same('x=1', $remoteRelationship['targetQuery']);
        $t->same('frag', $remoteRelationship['targetFragment']);
