    'preserves docx unsupported zip compression provenance without aborting ingestion' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $unsupportedPart = 'word/media/review-bzip2.bin';
        $unsupportedBytes = 'unsupported compression member bytes stay blocked';
        $parts[$unsupportedPart] = $unsupportedBytes;

        $document = (new DocxOpenXmlReader())->readZipPackage(
            docx_openxml_reader_zip_package_with_compression_methods(
                $parts,
                [
                    '[Content_Types].xml' => 0,
                    $unsupportedPart => 12,
                ],
            )
        );
        $package = $document->attr('docx')['packageProvenance'];
        $zipPackage = $package['zipPackage'];
        $summary = $package['summary'];
        $entry = $zipPackage['byPackagePath'][$unsupportedPart];
        $unsupportedEntries = $zipPackage['compressionMethods']['unsupportedEntries'];
        $methodBuckets = [];
        foreach ($summary['zipCompressionMethods'] as $bucket) {
            $methodBuckets[(int) $bucket['compressionMethod']] = $bucket;
        }

        $t->same('Imported DOCX Heading', $document->children[0]->attr('text'));
        $t->same(count($parts), $zipPackage['entryCount']);
        $t->same(count($parts), $zipPackage['fileEntryCount']);
        $t->same(count($parts) - 1, $zipPackage['loadedPartCount']);
        $t->same(1, $zipPackage['unsupportedCompressionMethodCount']);
        $t->same(count($parts) - 1, $zipPackage['compressionMethods']['supportedEntryCount']);
        $t->same(1, $zipPackage['compressionMethods']['storedEntryCount']);
        $t->same(count($parts) - 2, $zipPackage['compressionMethods']['deflatedEntryCount']);
        $t->same(strlen($unsupportedBytes), $zipPackage['compressionMethods']['unsupportedCompressedBytes']);
        $t->same(strlen($unsupportedBytes), $zipPackage['compressionMethods']['unsupportedUncompressedBytes']);
        $t->same($unsupportedPart, $unsupportedEntries[0]['name']);
        $t->same(12, $unsupportedEntries[0]['compressionMethod']);
        $t->same(false, $unsupportedEntries[0]['isDirectory']);

        $t->same(12, $entry['compressionMethod']);
        $t->same('unsupported', $entry['compressionMethodName']);
        $t->same(false, $entry['compressionSupported']);
        $t->same(false, $entry['loadedPart']);
        $t->same(strlen($unsupportedBytes), $entry['byteLength']);
        $t->same(strlen($unsupportedBytes), $entry['compressedByteLength']);
        $t->same(sprintf('%08x', crc32($unsupportedBytes)), $entry['crc32']);
        $t->same(['zip-file-entry', 'zip-unsupported-compression'], $entry['roles']);
        $t->same('docx-zip-entry-metadata-only', $entry['byteExposurePolicy']);
        $t->same(false, $entry['canExposeBytes']);
        $t->true(!isset($package['parts'][$unsupportedPart]), 'unsupported compression entry should not be loaded as a DOCX part');
        $t->true(!in_array($unsupportedPart, $zipPackage['loadedPartNames'], true), 'unsupported compression entry should stay out of loaded part names');

        $t->same(1, $summary['zipUnsupportedCompressionMethodCount']);
        $t->same(count($parts) - 1, $summary['zipSupportedCompressionEntryCount']);
        $t->same(1, $summary['zipStoredCompressionEntryCount']);
        $t->same(count($parts) - 2, $summary['zipDeflatedCompressionEntryCount']);
        $t->same(strlen($unsupportedBytes), $summary['zipUnsupportedCompressionCompressedByteLength']);
        $t->same(strlen($unsupportedBytes), $summary['zipUnsupportedCompressionUncompressedByteLength']);
        $t->same([$unsupportedPart], $summary['zipUnsupportedCompressionPartNames']);
        $t->same($unsupportedEntries, $summary['zipUnsupportedCompressionEntries']);
        $t->same(1, $methodBuckets[12]['entryCount']);
        $t->same(false, $methodBuckets[12]['isSupported']);
        $t->same(strlen($unsupportedBytes), $methodBuckets[12]['compressedBytes']);
        $t->same(strlen($unsupportedBytes), $methodBuckets[12]['uncompressedBytes']);
    },
    'summarizes docx source zip compression byte rollups for package review' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $storedNames = [
            'word/media/' => true,
            '[Content_Types].xml' => true,
            'word/media/review.png' => true,
        ];
        $zipParts = [
            ['name' => 'word/media/', 'data' => '', 'compressionMethod' => 0],
        ];
        $expectedStoredCompressedBytes = 0;
        $expectedStoredUncompressedBytes = 0;
        $expectedDeflatedCompressedBytes = 0;
        $expectedDeflatedUncompressedBytes = 0;
        foreach ($parts as $name => $data) {
            $stored = isset($storedNames[$name]);
            $zipParts[] = [
                'name' => $name,
                'data' => $data,
                'compressionMethod' => $stored ? 0 : 8,
            ];
            if ($stored) {
                $expectedStoredCompressedBytes += strlen($data);
                $expectedStoredUncompressedBytes += strlen($data);
                continue;
            }

            $deflated = gzdeflate($data);
            $t->true(is_string($deflated), "fixture {$name} should deflate");
            $expectedDeflatedCompressedBytes += strlen($deflated);
            $expectedDeflatedUncompressedBytes += strlen($data);
        }

        $document = (new DocxOpenXmlReader())->readZipPackage(ZipPackage::fromParts($zipParts));
        $package = $document->attr('docx')['packageProvenance'];
        $summary = $package['summary'];
        $compression = $package['zipPackage']['compressionMethods'];
        $entriesByName = [];
        foreach ($compression['entries'] as $entry) {
            $entriesByName[$entry['name']] = $entry;
        }

        $t->same(count($zipParts), $compression['entryCount']);
        $t->same(count($zipParts), $summary['zipCompressionEntryCount']);
        $t->same(count($zipParts), $compression['supportedEntryCount']);
        $t->same(count($zipParts), $summary['zipSupportedCompressionEntryCount']);
        $t->same(3, $compression['storedEntryCount']);
        $t->same(3, $summary['zipStoredEntryCount']);
        $t->same(count($zipParts) - 3, $compression['deflatedEntryCount']);
        $t->same(count($zipParts) - 3, $summary['zipDeflatedEntryCount']);
        $t->same(0, $compression['unsupportedCompressionMethodCount']);
        $t->same(0, $summary['zipUnsupportedCompressionMethodCount']);
        $t->same($expectedStoredCompressedBytes, $compression['storedCompressedBytes']);
        $t->same($expectedStoredCompressedBytes, $summary['zipStoredCompressedByteLength']);
        $t->same($expectedStoredUncompressedBytes, $compression['storedUncompressedBytes']);
        $t->same($expectedStoredUncompressedBytes, $summary['zipStoredUncompressedByteLength']);
        $t->same($expectedDeflatedCompressedBytes, $compression['deflatedCompressedBytes']);
        $t->same($expectedDeflatedCompressedBytes, $summary['zipDeflatedCompressedByteLength']);
        $t->same($expectedDeflatedUncompressedBytes, $compression['deflatedUncompressedBytes']);
        $t->same($expectedDeflatedUncompressedBytes, $summary['zipDeflatedUncompressedByteLength']);
        $t->same(0, $summary['zipUnsupportedCompressedByteLength']);
        $t->same(0, $summary['zipUnsupportedUncompressedByteLength']);
        $t->same('stored', $summary['zipCompressionMethods'][0]['compressionMethodName']);
        $t->same(3, $summary['zipCompressionMethods'][0]['entryCount']);
        $t->same($expectedStoredCompressedBytes, $summary['zipCompressionMethods'][0]['compressedBytes']);
        $t->same('deflated', $summary['zipCompressionMethods'][1]['compressionMethodName']);
        $t->same(count($zipParts) - 3, $summary['zipCompressionMethods'][1]['entryCount']);
        $t->same($expectedDeflatedCompressedBytes, $summary['zipCompressionMethods'][1]['compressedBytes']);
        $t->same(0, $entriesByName['[Content_Types].xml']['compressionMethod']);
        $t->same(8, $entriesByName['word/document.xml']['compressionMethod']);
        $t->same(true, $entriesByName['word/document.xml']['isSupported']);
    },
    'summarizes docx loaded package part zip compression buckets for review handoff' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['customXml/zip-compression-review.xml'] = '<zip-compression-review/>';
        $storedNames = [
            '[Content_Types].xml' => true,
            'word/media/review.png' => true,
            'word/styles.xml' => true,
        ];
        $zipParts = [
            ['name' => 'word/media/', 'data' => '', 'compressionMethod' => 0],
        ];
        $expectedByMethod = [
            0 => [
                'partNames' => [],
                'compressedByteLength' => 0,
                'uncompressedByteLength' => 0,
                'largestCompressedPart' => null,
            ],
            8 => [
                'partNames' => [],
                'compressedByteLength' => 0,
                'uncompressedByteLength' => 0,
                'largestCompressedPart' => null,
            ],
        ];
        foreach ($parts as $name => $data) {
            $method = isset($storedNames[$name]) ? 0 : 8;
            $compressed = $method === 8 ? gzdeflate($data) : $data;
            $t->true(is_string($compressed), "fixture {$name} should compress");
            $compressedLength = strlen($compressed);
            $zipParts[] = [
                'name' => $name,
                'data' => $data,
                'compressionMethod' => $method,
            ];
            $expectedByMethod[$method]['partNames'][] = $name;
            $expectedByMethod[$method]['compressedByteLength'] += $compressedLength;
            $expectedByMethod[$method]['uncompressedByteLength'] += strlen($data);
            $largestPart = $expectedByMethod[$method]['largestCompressedPart'];
            if (
                !is_array($largestPart)
                || $compressedLength > $largestPart['compressedByteLength']
                || ($compressedLength === $largestPart['compressedByteLength'] && strcmp($name, $largestPart['partName']) < 0)
            ) {
                $expectedByMethod[$method]['largestCompressedPart'] = [
                    'partName' => $name,
                    'compressedByteLength' => $compressedLength,
                    'bytes' => strlen($data),
                    'crc32' => sprintf('%08x', crc32($data)),
                    'sha256' => hash('sha256', $data),
                ];
            }
        }
        foreach ($expectedByMethod as &$expectedMethod) {
            sort($expectedMethod['partNames'], SORT_STRING);
        }
        unset($expectedMethod);

        $document = (new DocxOpenXmlReader())->readZipPackage(ZipPackage::fromParts($zipParts));
        $package = $document->attr('docx')['packageProvenance'];
        $summary = $package['summary'];
        $buckets = [];
        foreach ($summary['partZipCompressionMethods'] as $bucket) {
            $buckets[(int) $bucket['compressionMethod']] = $bucket;
        }

        $t->same('Imported DOCX Heading', $document->children[0]->attr('text'));
        $t->same(count($parts), $summary['partCount']);
        $t->same(count($parts) + 1, $summary['zipEntryCount']);
        $t->same(1, $summary['zipDirectoryEntryCount']);
        $t->same(count($parts), $summary['zipLoadedPartCount']);
        $t->same(2, $summary['partZipCompressionMethodCount']);
        $t->same([0 => 3, 8 => count($parts) - 3], $summary['partZipCompressionMethodCounts']);
        $t->same(
            $expectedByMethod[0]['compressedByteLength'] + $expectedByMethod[8]['compressedByteLength'],
            $summary['partZipCompressedByteLength']
        );
        $t->same(
            $expectedByMethod[0]['uncompressedByteLength'] + $expectedByMethod[8]['uncompressedByteLength'],
            $summary['partZipUncompressedByteLength']
        );
        $t->same(0, $summary['partZipUnsupportedCompressionPartCount']);
        $t->same(0, $summary['partZipDataDescriptorPartCount']);
        $t->same(2, count($summary['partZipCompressionMethods']));
        $t->true(!isset($package['parts']['word/media/']), 'directory entries should stay out of loaded package part compression buckets');

        $stored = $buckets[0];
        $t->same(0, $stored['compressionMethod']);
        $t->same('stored', $stored['compressionMethodName']);
        $t->same(3, $stored['partCount']);
        $t->same($expectedByMethod[0]['compressedByteLength'], $stored['compressedByteLength']);
        $t->same($expectedByMethod[0]['uncompressedByteLength'], $stored['uncompressedByteLength']);
        $t->same(3, $stored['supportedPartCount']);
        $t->same(0, $stored['unsupportedPartCount']);
        $t->same(0, $stored['dataDescriptorPartCount']);
        $t->same($expectedByMethod[0]['partNames'], $stored['partNames']);
        $t->same(3, $stored['contentTypeSourceCounts']['default']);
        $t->same(2, $stored['contentTypeBaseCounts']['application/xml']);
        $t->same(1, $stored['contentTypeBaseCounts']['image/png']);
        $t->same(1, $stored['roleCounts']['content-types']);
        $t->same(1, $stored['roleCounts']['document-relationship-target']);
        $t->same(1, $stored['roleCounts']['package-part']);
        $t->same($expectedByMethod[0]['largestCompressedPart']['partName'], $stored['largestCompressedPart']['partName']);
        $t->same($expectedByMethod[0]['largestCompressedPart']['compressedByteLength'], $stored['largestCompressedPart']['compressedByteLength']);
        $t->same($expectedByMethod[0]['largestCompressedPart']['bytes'], $stored['largestCompressedPart']['bytes']);
        $t->same($expectedByMethod[0]['largestCompressedPart']['crc32'], $stored['largestCompressedPart']['crc32']);
        $t->same($expectedByMethod[0]['largestCompressedPart']['sha256'], $stored['largestCompressedPart']['sha256']);
        $t->same(true, $stored['largestCompressedPart']['compressionSupported']);

        $deflated = $buckets[8];
        $t->same(8, $deflated['compressionMethod']);
        $t->same('deflated', $deflated['compressionMethodName']);
        $t->same(count($parts) - 3, $deflated['partCount']);
        $t->same($expectedByMethod[8]['compressedByteLength'], $deflated['compressedByteLength']);
        $t->same($expectedByMethod[8]['uncompressedByteLength'], $deflated['uncompressedByteLength']);
        $t->same(count($parts) - 3, $deflated['supportedPartCount']);
        $t->same(0, $deflated['unsupportedPartCount']);
        $t->same(0, $deflated['dataDescriptorPartCount']);
        $t->same($expectedByMethod[8]['partNames'], $deflated['partNames']);
        $t->same(4, $deflated['contentTypeSourceCounts']['default']);
        $t->same(2, $deflated['contentTypeSourceCounts']['override']);
        $t->same(2, $deflated['contentTypeBaseCounts']['application/xml']);
        $t->same(2, $deflated['contentTypeBaseCounts']['application/vnd.openxmlformats-package.relationships+xml']);
        $t->same(1, $deflated['contentTypeBaseCounts']['application/vnd.openxmlformats-package.core-properties+xml']);
        $t->same(1, $deflated['contentTypeBaseCounts']['application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml']);
        $t->same(1, $deflated['roleCounts']['office-document']);
        $t->same(1, $deflated['roleCounts']['package-relationships']);
        $t->same(1, $deflated['roleCounts']['office-document-relationships']);
        $t->same($expectedByMethod[8]['largestCompressedPart']['partName'], $deflated['largestCompressedPart']['partName']);
        $t->same($expectedByMethod[8]['largestCompressedPart']['compressedByteLength'], $deflated['largestCompressedPart']['compressedByteLength']);
        $t->same($expectedByMethod[8]['largestCompressedPart']['bytes'], $deflated['largestCompressedPart']['bytes']);
        $t->same($expectedByMethod[8]['largestCompressedPart']['crc32'], $deflated['largestCompressedPart']['crc32']);
        $t->same($expectedByMethod[8]['largestCompressedPart']['sha256'], $deflated['largestCompressedPart']['sha256']);
        $t->same(true, $deflated['largestCompressedPart']['compressionSupported']);
    },
    'summarizes docx zip expansion ratios for package review handoff' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $expansionPart = 'customXml/zip-expansion-review.xml';
        $parts[$expansionPart] = str_repeat('<review>zip expansion ratio</review>', 512);
        $storedNames = [
            'word/media/' => true,
            '[Content_Types].xml' => true,
            'word/media/review.png' => true,
        ];
        $zipParts = [
            ['name' => 'word/media/', 'data' => '', 'compressionMethod' => 0],
        ];
        $expectedZipCompressedBytes = 0;
        $expectedZipUncompressedBytes = 0;
        $expectedByMethod = [
            0 => ['compressedByteLength' => 0, 'uncompressedByteLength' => 0],
            8 => ['compressedByteLength' => 0, 'uncompressedByteLength' => 0],
        ];
        $expectedPartCompressedBytes = 0;
        $expectedPartUncompressedBytes = 0;
        $expectedEntryRatios = [];
        $ratio = static function (int $uncompressedBytes, int $compressedBytes): ?float {
            if ($uncompressedBytes === 0) {
                return 0.0;
            }

            return $compressedBytes === 0 ? null : $uncompressedBytes / $compressedBytes;
        };

        foreach ($parts as $name => $data) {
            $method = isset($storedNames[$name]) ? 0 : 8;
            $compressed = $method === 8 ? gzdeflate($data) : $data;
            $t->true(is_string($compressed), "fixture {$name} should compress");
            $compressedLength = strlen($compressed);
            $uncompressedLength = strlen($data);
            $zipParts[] = [
                'name' => $name,
                'data' => $data,
                'compressionMethod' => $method,
            ];
            $expectedZipCompressedBytes += $compressedLength;
            $expectedZipUncompressedBytes += $uncompressedLength;
            $expectedPartCompressedBytes += $compressedLength;
            $expectedPartUncompressedBytes += $uncompressedLength;
            $expectedByMethod[$method]['compressedByteLength'] += $compressedLength;
            $expectedByMethod[$method]['uncompressedByteLength'] += $uncompressedLength;
            $expectedEntryRatios[$name] = $ratio($uncompressedLength, $compressedLength);
        }

        $document = (new DocxOpenXmlReader())->readZipPackage(ZipPackage::fromParts($zipParts));
        $package = $document->attr('docx')['packageProvenance'];
        $zipPackage = $package['zipPackage'];
        $summary = $package['summary'];
        $entry = $zipPackage['byPackagePath'][$expansionPart];
        $inventory = $package['parts'][$expansionPart];
        $partBuckets = [];
        foreach ($summary['partZipCompressionMethods'] as $bucket) {
            $partBuckets[(int) $bucket['compressionMethod']] = $bucket;
        }
        $zipBuckets = [];
        foreach ($summary['zipCompressionMethods'] as $bucket) {
            $zipBuckets[(int) $bucket['compressionMethod']] = $bucket;
        }

        $t->same('Imported DOCX Heading', $document->children[0]->attr('text'));
        $t->same($expectedZipCompressedBytes, $zipPackage['compressedByteLength']);
        $t->same($expectedZipUncompressedBytes, $zipPackage['uncompressedByteLength']);
        $t->same($ratio($expectedZipUncompressedBytes, $expectedZipCompressedBytes), $zipPackage['expansionRatio']);
        $t->same(1, $zipPackage['zeroByteEntryCount']);
        $t->same(0, $zipPackage['zeroByteFileCount']);
        $t->same(1, $zipPackage['emptyDirectoryEntryCount']);
        $t->same(true, $zipPackage['hasZeroByteEntries']);
        $t->same(0, $zipPackage['unknownExpansionRatioEntryCount']);
        $t->same(false, $zipPackage['hasUnknownExpansionRatioEntries']);
        $t->same([], $zipPackage['unknownExpansionRatioEntries']);
        $t->same($expansionPart, $zipPackage['largestUncompressedEntry']['name']);
        $t->same($expectedEntryRatios[$expansionPart], $zipPackage['largestUncompressedEntry']['expansionRatio']);

        $t->same($expectedEntryRatios[$expansionPart], $entry['expansionRatio']);
        $t->same(false, $entry['hasUnknownExpansionRatio']);
        $t->same($expectedEntryRatios[$expansionPart], $inventory['zipExpansionRatio']);
        $t->same(false, $inventory['zipHasUnknownExpansionRatio']);
        $t->same('docx-zip-entry-metadata-only', $entry['byteExposurePolicy']);
        $t->same(false, $entry['canExposeBytes']);

