      <c:barChart>
        <c:barDir val="col"/>
        <c:ser>
          <c:idx val="0"/><c:order val="0"/>
          <c:invertIfNegative val="1"/>
          <c:dPt>
            <c:idx val="1"/>
            <c:invertIfNegative val="0"/>
            <c:marker><c:symbol val="diamond"/><c:size val="7"/></c:marker>
